#include <bits/stdc++.h>
using namespace std;
using ll=long long;
struct DSU{vector<int>p,sz;DSU(int n):p(n),sz(n,1){iota(p.begin(),p.end(),0);}int find(int x){return p[x]==x?x:p[x]=find(p[x]);}void join(int a,int b){a=find(a);b=find(b);if(a!=b){if(sz[a]<sz[b])swap(a,b);p[b]=a;sz[a]+=sz[b];}}};
struct BIT{int n;vector<int>t;BIT(int n=0):n(n),t(n+1){}void add(int x,int v){for(++x;x<=n;x+=x&-x)t[x]+=v;}int sum(int x){int r=0;for(;x>0;x-=x&-x)r+=t[x];return r;}int kth(int k){int p=0;for(int step=1<<20;step;step>>=1)if(p+step<=n&&t[p+step]<k){p+=step;k-=t[p];}return p;}};
ll power(ll a,ll b,ll mod=1000000007){ll r=1;for(;b;b>>=1,a=a*a%mod)if(b&1)r=r*a%mod;return r;}
struct TopK{int k;multiset<ll>small,big;ll sum=0;TopK(int k):k(k){}void rebalance(){while((int)big.size()>k){auto it=big.begin();sum-=*it;small.insert(*it);big.erase(it);}while((int)big.size()<k&&!small.empty()){auto it=prev(small.end());sum+=*it;big.insert(*it);small.erase(it);}while(!small.empty()&&!big.empty()&&*prev(small.end())>*big.begin()){ll a=*prev(small.end()),b=*big.begin();small.erase(prev(small.end()));big.erase(big.begin());small.insert(b);big.insert(a);sum+=a-b;}}void add(ll v){if(v>0){small.insert(v);rebalance();}}void erase(ll v){if(v<=0)return;auto it=big.find(v);if(it!=big.end()){sum-=v;big.erase(it);}else small.erase(small.find(v));rebalance();}};int main(){int n,len;cin>>n>>len;vector<ll>a(n);for(auto&v:a)cin>>v;int k;cin>>k;TopK positive(k),negative(k);ll sum=0,ans=0;for(int i=0;i<n;i++){sum+=a[i];positive.add(a[i]);negative.add(-a[i]);if(i>=len){sum-=a[i-len];positive.erase(a[i-len]);negative.erase(-a[i-len]);}if(i>=len-1)ans=max({ans,sum+2*negative.sum,-sum+2*positive.sum});}cout<<ans<<'\n';}
